import{_ as a,o as i,c as n,a2 as o}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Ley de Protección Ambiental","description":"","frontmatter":{},"headers":[],"relativePath":"es/46-环境保护法.md","filePath":"es/46-环境保护法.md"}'),t={name:"es/46-环境保护法.md"};function s(l,e,r,d,c,u){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="ley-de-proteccion-ambiental" tabindex="-1">Ley de Protección Ambiental <a class="header-anchor" href="#ley-de-proteccion-ambiental" aria-label="Permalink to &quot;Ley de Protección Ambiental&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>46</td></tr><tr><td>Módulo</td><td>Sistema Legal y Marco de Gobernanza</td></tr><tr><td>Palabras clave</td><td>Protección ambiental, Origen del Universo, Simbiosis ecológica, Desarrollo sostenible, Prevención de la contaminación</td></tr></tbody></table><h2 id="i-proposito-legislativo-y-principios-basicos" tabindex="-1">I. Propósito Legislativo y Principios Básicos <a class="header-anchor" href="#i-proposito-legislativo-y-principios-basicos" aria-label="Permalink to &quot;I. Propósito Legislativo y Principios Básicos&quot;">​</a></h2><p>La <em>Ley de Protección Ambiental</em> es una de las cinco leyes complementarias de la Civilización Simbiótica del Ancla. Su objetivo es proteger el entorno ecológico y el Origen del Universo dentro del Universo Hengyuan, establecer la filosofía de gobernanza ambiental de &quot;evolución simbiótica, desarrollo sostenible&quot;, evitar la destrucción del ecosistema cósmico por el desarrollo depredador, y salvaguardar la base de supervivencia para el avance conjunto de las Diez Mil Razas.</p><p>Esta Ley establece los siguientes principios básicos:</p><table tabindex="0"><thead><tr><th>Principio</th><th>Contenido</th></tr></thead><tbody><tr><td>Protección del Origen</td><td>El Origen del Universo es la base de toda vida y evolución; debe protegerse de forma prioritaria; se prohíbe la explotación destructiva</td></tr><tr><td>Simbiosis Ecológica</td><td>La humanidad y la naturaleza, todas las razas y los ecosistemas están en relación simbiótica; destruir la ecología es destruir la propia base de supervivencia</td></tr><tr><td>Sostenibilidad</td><td>Todas las actividades de desarrollo deben considerar los intereses de las generaciones presentes y futuras; se opone al agotamiento de recursos</td></tr><tr><td>Prevención Primero</td><td>La protección ambiental está orientada a la prevención; establece una institución de evaluación de impacto ambiental para evitar que ocurra la contaminación</td></tr><tr><td>Responsabilidad del Contaminador</td><td>Las entidades que causen contaminación ambiental y destrucción ecológica deben asumir la responsabilidad del tratamiento y la compensación</td></tr><tr><td>Participación Pública</td><td>Fomenta la participación pública en la protección ambiental; garantiza el derecho a saber y a participar en el medio ambiente</td></tr><tr><td>Coordinación Transplanar</td><td>La protección ambiental avanza de forma coordinada entre planos; establece un mecanismo de cooperación de gobernanza ambiental transplanar</td></tr></tbody></table><h2 id="ii-ambito-de-la-proteccion-ambiental" tabindex="-1">II. Ámbito de la Protección Ambiental <a class="header-anchor" href="#ii-ambito-de-la-proteccion-ambiental" aria-label="Permalink to &quot;II. Ámbito de la Protección Ambiental&quot;">​</a></h2><p>El ámbito ambiental protegido por esta Ley incluye todos los ecosistemas y elementos ambientales dentro del Universo Hengyuan:</p><ol><li><strong>Entorno Atmosférico</strong>: Incluye la concentración de energía y el equilibrio de composición de la atmósfera y las capas energéticas de cada planeta.</li><li><strong>Entorno Hídrico</strong>: Incluye la calidad y cantidad de las aguas superficiales, subterráneas, los océanos y las aguas energéticas entre planos.</li><li><strong>Entorno del Suelo</strong>: Incluye la calidad y fertilidad de los suelos terrestres y de las vetas minerales de recursos de cultivo.</li><li><strong>Diversidad Biológica</strong>: Incluye la protección de especies y hábitats de toda la flora, fauna, microorganismos y vidas extrañas.</li><li><strong>Entorno Energético</strong>: Incluye la concentración y el equilibrio de distribución de la energía espiritual del cielo y la tierra, la energía originaria y los fragmentos de leyes.</li><li><strong>Entorno Espacial</strong>: Incluye la estabilidad espacial de los planos, las fisuras espaciales y la seguridad ambiental del espacio plegado.</li><li><strong>Entorno del Dominio de la Conciencia</strong>: Incluye la limpieza informativa del espacio de conciencia colectiva y la prevención de la contaminación espiritual.</li></ol><h2 id="iii-instituciones-principales" tabindex="-1">III. Instituciones Principales <a class="header-anchor" href="#iii-instituciones-principales" aria-label="Permalink to &quot;III. Instituciones Principales&quot;">​</a></h2><h3 id="i-institucion-de-evaluacion-de-impacto-ambiental" tabindex="-1">(I) Institución de Evaluación de Impacto Ambiental <a class="header-anchor" href="#i-institucion-de-evaluacion-de-impacto-ambiental" aria-label="Permalink to &quot;(I) Institución de Evaluación de Impacto Ambiental&quot;">​</a></h3><p>Todos los proyectos de desarrollo y construcción que puedan tener un impacto significativo en el medio ambiente deben someterse a evaluación de impacto ambiental antes de iniciar las obras. El contenido de la evaluación incluye: el impacto del proyecto en los elementos ambientales atmosféricos, hídricos, del suelo, biológicos, energéticos, espaciales, etc., las medidas de prevención y mitigación, la evaluación de riesgos ambientales, etc. Los proyectos que no aprueben la evaluación de impacto ambiental no podrán iniciar la construcción.</p><h3 id="ii-institucion-de-permiso-de-vertidos-y-control-de-cantidades-totales" tabindex="-1">(II) Institución de Permiso de Vertidos y Control de Cantidades Totales <a class="header-anchor" href="#ii-institucion-de-permiso-de-vertidos-y-control-de-cantidades-totales" aria-label="Permalink to &quot;(II) Institución de Permiso de Vertidos y Control de Cantidades Totales&quot;">​</a></h3><p>El estado implementa gestión de permisos y control de cantidades totales para los vertidos de contaminantes. Las unidades vertedoras deben obtener permisos de vertido de contaminantes y verter conforme a los tipos, concentraciones y cantidades totales especificados en los permisos. El estado determina la cantidad total de vertidos de contaminantes para cada región y plano según la capacidad de carga ambiental, descomponiéndola e implementándola nivel por nivel.</p><h3 id="iii-institucion-de-lineas-rojas-de-proteccion-ecologica" tabindex="-1">(III) Institución de Líneas Rojas de Protección Ecológica <a class="header-anchor" href="#iii-institucion-de-lineas-rojas-de-proteccion-ecologica" aria-label="Permalink to &quot;(III) Institución de Líneas Rojas de Protección Ecológica&quot;">​</a></h3><p>El estado delimita líneas rojas de protección ecológica en zonas de especial valor ecológico, incluyendo:</p><table tabindex="0"><thead><tr><th>Tipo de Línea Roja</th><th>Contenido Protegido</th></tr></thead><tbody><tr><td>Zona de Protección del Origen</td><td>Zonas centrales de producción de energía del Origen del Universo; se prohíben todas las actividades de desarrollo</td></tr><tr><td>Hábitat de Especies</td><td>Hábitats centrales de especies raras y en peligro; se prohíben la destrucción y la perturbación</td></tr><tr><td>Zona de Barrera Ecológica</td><td>Ecosistemas clave que mantienen el equilibrio ecológico regional; desarrollo restringido</td></tr><tr><td>Lugares Sagrados de Cultivo</td><td>Zonas ricas en energía con especial valor de cultivo; se implementa uso protector</td></tr><tr><td>Franja de Unión de Planos</td><td>Franjas de transición ecológica entre planos; se prohíbe el desarrollo espacialmente destructivo</td></tr></tbody></table><h3 id="iv-institucion-de-monitoreo-y-alerta-temprana-ambiental" tabindex="-1">(IV) Institución de Monitoreo y Alerta Temprana Ambiental <a class="header-anchor" href="#iv-institucion-de-monitoreo-y-alerta-temprana-ambiental" aria-label="Permalink to &quot;(IV) Institución de Monitoreo y Alerta Temprana Ambiental&quot;">​</a></h3><p>El estado establece una red de monitoreo ambiental que cubre todo el universo, monitoreando en tiempo real los cambios de los elementos ambientales. Para los posibles eventos mayores de contaminación ambiental y destrucción ecológica, se establece un mecanismo de alerta temprana, emitiendo oportunamente información de alerta e iniciando respuesta de emergencia.</p><h3 id="v-institucion-de-compensacion-ecologica" tabindex="-1">(V) Institución de Compensación Ecológica <a class="header-anchor" href="#v-institucion-de-compensacion-ecologica" aria-label="Permalink to &quot;(V) Institución de Compensación Ecológica&quot;">​</a></h3><p>Las regiones y grupos cuyo desarrollo está restringido por la protección ambiental tienen derecho a recibir compensación ecológica. Los fondos de compensación ecológica provienen de la acumulación pública y los rendimientos del desarrollo de recursos, utilizados para el desarrollo económico de las regiones compensadas y la mejora de la vida de los residentes.</p><h2 id="iv-regulacion-ambiental-de-las-actividades-de-cultivo" tabindex="-1">IV. Regulación Ambiental de las Actividades de Cultivo <a class="header-anchor" href="#iv-regulacion-ambiental-de-las-actividades-de-cultivo" aria-label="Permalink to &quot;IV. Regulación Ambiental de las Actividades de Cultivo&quot;">​</a></h2><p>El impacto de las actividades de cultivo en el medio ambiente es un ámbito especial de la protección ambiental en el Universo Hengyuan; esta Ley establece disposiciones regulatorias dedicadas:</p><ol><li><strong>Regulación de la Extracción de Energía</strong>: La extracción de recursos de cultivo debe ajustarse al principio de sostenibilidad; se prohíbe la extracción destructiva que conduzca al agotamiento de la energía. El volumen de extracción no debe superar la tasa de recuperación natural de la energía regional.</li><li><strong>Tratamiento de Residuos de Cultivo</strong>: Los residuos energéticos, píldoras desechadas, artefactos dañados y otros residuos generados durante el cultivo deben tratarse conforme a las normas; se prohíbe el desecho arbitrario que cause contaminación energética.</li><li><strong>Evaluación Ambiental del Cultivo Avanzado</strong>: Los avances y retiros de los cultivadores avanzados pueden tener impactos significativos en el entorno circundante; debe realizarse evaluación ambiental con antelación y adoptarse medidas de protección.</li><li><strong>Permiso de Desarrollo de Planos</strong>: El desarrollo de nuevos planos debe someterse a evaluación ambiental y estudio ecológico; el desarrollo solo puede proceder tras formular un plan de protección ecológica.</li><li><strong>Protección de Hábitats de Vidas Extrañas</strong>: Los hábitats de las vidas extrañas se incluyen en las líneas rojas de protección ecológica; se prohíben la exploración y el desarrollo sin permiso.</li></ol><h2 id="v-responsabilidad-legal" tabindex="-1">V. Responsabilidad Legal <a class="header-anchor" href="#v-responsabilidad-legal" aria-label="Permalink to &quot;V. Responsabilidad Legal&quot;">​</a></h2><p>Los actos que violen las disposiciones de esta Ley asumirán las siguientes responsabilidades según la gravedad de las circunstancias:</p><ul><li>Quienes inicien la construcción sin aprobar la evaluación de impacto ambiental serán ordenados a detener la construcción, restaurar el estado original y multados.</li><li>Quienes viertan contaminantes por encima de los estándares serán ordenados a tratar en un plazo y multados; en casos graves, ordenados a suspender operaciones y cerrar.</li><li>Quienes destruyan las líneas rojas de protección ecológica serán ordenados a restaurar el estado original y multados; en casos graves, se persigue responsabilidad penal.</li><li>Quienes extraigan destructivamente los recursos de cultivo tendrán confiscadas sus ganancias ilegales, serán multados y se les revocarán los permisos de extracción.</li><li>Quienes causen accidentes mayores de contaminación ambiental asumirán responsabilidad de indemnización; si constituye delito, se persigue responsabilidad penal.</li><li>Los supervisores ambientales que descuiden sus deberes o abusen de su poder serán sancionados; si constituye delito, se persigue responsabilidad penal.</li></ul><h2 id="vi-participacion-publica-y-accion-de-interes-publico-ambiental" tabindex="-1">VI. Participación Pública y Acción de Interés Público Ambiental <a class="header-anchor" href="#vi-participacion-publica-y-accion-de-interes-publico-ambiental" aria-label="Permalink to &quot;VI. Participación Pública y Acción de Interés Público Ambiental&quot;">​</a></h2><p>El público tiene derecho a participar en la protección ambiental, con canales específicos que incluyen:</p><ol><li>Presentar opiniones y sugerencias sobre los proyectos de evaluación de impacto ambiental.</li><li>Denunciar y quejarse de los actos de contaminación del medio ambiente y destrucción de la ecología.</li><li>Establecer organizaciones de protección ambiental conforme a la ley, participando en la supervisión ambiental y actividades de interés público.</li><li>Por los actos que contaminen el medio ambiente, destruyan la ecología y dañen los intereses públicos, las organizaciones de protección ambiental pueden presentar acciones de interés público ambiental ante el Tribunal Simbiótico.</li></ol><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La <em>Ley de Protección Ambiental</em> es la garantía legal de la filosofía de desarrollo sostenible de la Civilización Simbiótica del Ancla. Al establecer instituciones como la evaluación de impacto ambiental, las líneas rojas de protección ecológica y el control de cantidades totales, integra la protección ambiental en todas las actividades de desarrollo y cultivo, asegurando la sostenibilidad del Origen del Universo y del ecosistema, y custodiando la base eterna de supervivencia para el avance conjunto de las Diez Mil Razas.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitución Simbiótica: Principios Generales)</li><li>39-住房与环境保障 (Vivienda y Protección Ambiental)</li><li>15-能量循环与转化法则 (Ley de Circulación y Transformación de la Energía)</li><li>53-奇特生命识别标准 (Estándares de Identificación de Vidas Extrañas)</li></ul>',34)])])}const b=a(t,[["render",s]]);export{m as __pageData,b as default};
